/* HEXA BATTLEGROUNDS setup — PART 21 OF 55. Run parts in order. Safe to re-run. */ alter table teams add column if not exists pos_at timestamptz; alter table teams add column if not exists travel_fx real; alter table teams add column if not exists travel_fy real; alter table teams add column if not exists zone_hit_at timestamptz; alter table teams add column if not exists last_steer_ping timestamptz; alter table arenas add column if not exists red_x real; alter table arenas add column if not exists red_y real; alter table arenas add column if not exists red_r real; alter table arenas add column if not exists red_at timestamptz; alter table arenas add column if not exists last_red_at timestamptz; alter table battles add column if not exists x real; alter table battles add column if not exists y real; create or replace function _defaults() returns jsonb language sql immutable as $$ select jsonb_build_object( 'pts_standard', 100, 'pts_hard', 150, 'pts_battle', 125, 'pts_airdrop', 75, 'pts_relay_bonus', 25, 'pts_relocation', 40, 'pen_recovery', 40, 'finale_max', 300, 'finale_entry_max', 200, 'finale_exchange_max', 200, 'hp_max', 100, 'hp_respawn', 50, 'dmg_fail', 10, 'dmg_zone', 15, 'shield_max', 60, 'shuttle_seconds', 10, 'roles_seconds', 15, 'bus_size', 3, 'arena_size', 15, 'attack_cooldown', 90, 'protect_seconds', 120, 'recovery_seconds', 120, 'zone_warning', 60, 'airdrop_window', 180, 'airdrop_interval', 0, 'intel_fallback', 90, 'relay_chance', 20, 'hint_cost', 15, 'alliance_minutes', 10, 'alliance_cost', 10, 'chat_limit', 6, 'drop_seconds', 8, 'visit_missions', 2, 'zone_auto', 0, 'zone_schedule', '20,40,55,70,85', 'sync_seconds', 0, 'auto_pacing', 0, 'phase_schedule', '2,12,30,50', 'duel_phase', 2, 'mission_time_pct', 100, 'pin_length', 6, 'move_speed', 25, 'loc_radius', 35, 'engage_range', 60, 'zone_tick_seconds', 6, 'zone_tick_damage', 4, 'red_interval', 0, 'red_warning', 20, 'red_damage', 30, 'red_radius', 80 ) $$; create or replace function _loc_xy(p_loc text) returns float8[] language sql stable as $$ select array[x::float8, y::float8] from locations where id = p_loc $$; create or replace function _team_xy(t teams) returns float8[] language plpgsql stable as $$ declare d float8[]; p float8; begin if t.state = 'traveling' and t.travel_to is not null and t.travel_arrive_at is not null then d := _loc_xy(t.travel_to); if t.travel_fx is not null and d is not null then p := least(1, greatest(0, extract(epoch from now() - t.travel_started_at) / greatest(0.001, extract(epoch from t.travel_arrive_at - t.travel_started_at)))); return array[t.travel_fx + (d[1] - t.travel_fx) * p, t.travel_fy + (d[2] - t.travel_fy) * p]; end if; end if; if t.pos_x is not null then return array[t.pos_x::float8, t.pos_y::float8]; end if; return coalesce(_loc_xy(t.location_id), array[0.5, 0.93]); end $$; create or replace function _teams_pos_sync() returns trigger language plpgsql as $$ declare xy float8[]; begin if tg_op = 'INSERT' or (new.location_id is distinct from old.location_id and new.pos_x is not distinct from old.pos_x and new.pos_y is not distinct from old.pos_y) then if new.location_id is not null then xy := _loc_xy(new.location_id); if xy is not null then new.pos_x := xy[1]; new.pos_y := xy[2]; new.pos_at := now(); end if; end if; end if; return new; end $$; drop trigger if exists teams_pos_sync on teams; create trigger teams_pos_sync before insert or update on teams for each row execute function _teams_pos_sync(); update teams t set pos_x = l.x, pos_y = l.y, pos_at = now() from locations l where l.id = t.location_id and t.pos_x is null; create or replace function _zone_circle(p_event uuid, p_stage int) returns float8[] language plpgsql stable as $$ declare radii float8[] := array[0.9, 0.5, 0.36, 0.24, 0.14, 0.035]; tr float8[]; seed int; cx float8 := 0.5; cy float8 := 0.5; nx float8; ny float8; ang float8; mag float8; d float8; room float8; k int; begin tr := coalesce(_loc_xy('tr14'), array[0.5, 0.65]); select mission_seed into seed from events where id = p_event; p_stage := greatest(0, least(5, coalesce(p_stage, 0))); for k in 1..p_stage loop if k = 5 then cx := tr[1]; cy := tr[2]; exit; end if; ang := (abs(hashtext(coalesce(seed, 0)::text || 'zang' || k)) % 3600) / 3600.0 * 2 * pi(); mag := (abs(hashtext(coalesce(seed, 0)::text || 'zmag' || k)) % 1000) / 1000.0 * 0.45 * radii[k + 1]; nx := tr[1] + cos(ang) * mag; ny := tr[2] + sin(ang) * mag; room := radii[k] - radii[k + 1]; d := sqrt((nx - cx) ^ 2 + (ny - cy) ^ 2); if d > room and d > 0 then nx := cx + (nx - cx) * room / d; ny := cy + (ny - cy) * room / d; end if; while sqrt((nx - tr[1]) ^ 2 + (ny - tr[2]) ^ 2) > radii[k + 1] * 0.7 loop nx := nx + (tr[1] - nx) * 0.3; ny := ny + (tr[2] - ny) * 0.3; end loop; cx := nx; cy := ny; end loop; return array[cx, cy, radii[p_stage + 1]]; end $$; create or replace function _in_circle(c float8[], x float8, y float8) returns boolean language sql immutable as $$ select c is null or sqrt((x - c[1]) ^ 2 + (y - c[2]) ^ 2) <= c[3] $$; create or replace function _nearest_safe_xy(p_event uuid, p_stage int, p_x float8, p_y float8) returns text language sql stable as $$ select id from locations where enabled and kind <> 'start' and _in_circle(_zone_circle(p_event, p_stage), x, y) order by _in_circle(_zone_circle(p_event, least(5, p_stage + 1)), x, y) desc, (x - p_x) ^ 2 + (y - p_y) ^ 2 limit 1 $$; create or replace function _zone_publish(p_arena uuid) returns void language plpgsql as $$ declare a arenas; cur float8[]; nxt float8[]; begin select * into a from arenas where id = p_arena; if a.id is null then return; end if; cur := _zone_circle(a.event_id, a.zone_stage); if a.zone_next_at is not null and a.zone_stage < 5 then nxt := _zone_circle(a.event_id, a.zone_stage + 1); end if; update arenas set overlay = (overlay - 'zone' - 'red') || jsonb_build_object( 'zone', jsonb_build_object('stage', a.zone_stage, 'cur', to_jsonb(cur), 'next', to_jsonb(nxt), 'next_at', a.zone_next_at), 'world', jsonb_build_object('speed', _cfg(a.event_id, 'move_speed') / 1000.0, 'loc_radius', _cfg(a.event_id, 'loc_radius') / 1000.0, 'engage_range', _cfg(a.event_id, 'engage_range') / 1000.0)) || case when a.red_at is not null then jsonb_build_object('red', jsonb_build_object('x', a.red_x, 'y', a.red_y, 'r', a.red_r, 'at', a.red_at)) else '{}'::jsonb end where id = p_arena; end $$; create or replace function _loc_at(p_event uuid, p_x float8, p_y float8) returns text language sql stable as $$ select id from locations where enabled and kind <> 'start' and (x - p_x) ^ 2 + (y - p_y) ^ 2 <= (_cfg(p_event, 'loc_radius') / 1000.0) ^ 2 order by (x - p_x) ^ 2 + (y - p_y) ^ 2 limit 1 $$; create or replace function _apply_zone(p_arena uuid) returns void language plpgsql as $$ declare a arenas; c float8[]; r teams; xy float8[]; v_out int := 0; begin select * into a from arenas where id = p_arena; c := _zone_circle(a.event_id, a.zone_stage); for r in select * from teams where arena_id = p_arena and ready loop xy := _team_xy(r); if not _in_circle(c, xy[1], xy[2]) then v_out := v_out + 1; perform _ping_team(r.id, 'zone'); end if; end loop; if v_out > 0 then perform _feed(p_arena, 'zone.outside', jsonb_build_object('squads', v_out)); end if; perform _zone_publish(p_arena); end $$; create or replace function _red_spawn(p_arena uuid, p_x float8 default null, p_y float8 default null) returns jsonb language plpgsql as $$ declare a arenas; c float8[]; tr float8[]; rr float8; x float8; y float8; i int; ang float8; mag float8; begin select * into a from arenas where id = p_arena for update; if a.phase <> 'play' then raise exception 'WRONG_PHASE'; end if; if a.red_at is not null then raise exception 'RED_ZONE_ACTIVE'; end if; c := _zone_circle(a.event_id, a.zone_stage); tr := _loc_xy('tr14'); rr := _cfg(a.event_id, 'red_radius') / 1000.0; if p_x is not null then x := greatest(0.04, least(0.96, p_x)); y := greatest(0.04, least(0.96, p_y)); else for i in 1..30 loop ang := random() * 2 * pi(); mag := sqrt(random()) * greatest(0.01, c[3] - rr * 0.5); x := greatest(0.05, least(0.95, c[1] + cos(ang) * mag)); y := greatest(0.05, least(0.95, c[2] + sin(ang) * mag)); exit when sqrt((x - tr[1]) ^ 2 + (y - tr[2]) ^ 2) > rr + 0.05; end loop; end if; update arenas set red_x = x, red_y = y, red_r = rr, red_at = now() + _secs(_cfg(a.event_id, 'red_warning')) where id = p_arena; perform _feed(p_arena, 'redzone.warning', jsonb_build_object('location', _loc_at(a.event_id, x, y))); perform _zone_publish(p_arena); perform _ping_arena(p_arena, 'redzone'); return jsonb_build_object('x', x, 'y', y, 'r', rr); end $$; create or replace function _red_strike(p_arena uuid) returns void language plpgsql as $$ declare a arenas; r teams; xy float8[]; v_hits int[] := '{}'; v_dmg int; d int; begin select * into a from arenas where id = p_arena for update; if a.red_at is null then return; end if; v_dmg := _cfg(a.event_id, 'red_damage'); for r in select * from teams where arena_id = p_arena and ready and state <> 'recovery' loop xy := _team_xy(r); if sqrt((xy[1] - a.red_x) ^ 2 + (xy[2] - a.red_y) ^ 2) <= a.red_r then d := _damage(r.id, v_dmg, 'redzone', 'rz-' || extract(epoch from a.red_at)::bigint, 'Caught in a red zone'); v_hits := v_hits || r.number; perform _ping_team(r.id, 'redzone'); end if; end loop; update arenas set red_x = null, red_y = null, red_r = null, red_at = null, last_red_at = now() where id = p_arena; perform _feed(p_arena, 'redzone.strike', jsonb_build_object('hits', to_jsonb(v_hits))); perform _zone_publish(p_arena); perform _ping_arena(p_arena, 'redzone'); end $$; create or replace function captain_steer(p_token text, p_x float8, p_y float8) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; cur float8[]; dt float8; maxd float8; d float8; nx float8; ny float8; v_loc text; v_others int; v_ping boolean; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state = 'recovery' then raise exception 'BUSY'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; if p_x is null or p_y is null or p_x = 'NaN'::float8 or p_y = 'NaN'::float8 or abs(p_x) = 'Infinity'::float8 or abs(p_y) = 'Infinity'::float8 then raise exception 'BAD_REQUEST'; end if; cur := _team_xy(t); dt := least(4, greatest(0, extract(epoch from now() - coalesce(case when t.state = 'traveling' then now() else t.pos_at end, now() - interval '1 second')))); if t.state = 'traveling' then dt := 0.25; end if; maxd := (_cfg(t.event_id, 'move_speed') / 1000.0) * dt * 1.25 + 0.003; nx := greatest(0.035, least(0.965, p_x)); ny := greatest(0.035, least(0.965, p_y)); d := sqrt((nx - cur[1]) ^ 2 + (ny - cur[2]) ^ 2); if d > maxd then nx := cur[1] + (nx - cur[1]) * maxd / d; ny := cur[2] + (ny - cur[2]) * maxd / d; end if; v_loc := _loc_at(t.event_id, nx, ny); if v_loc is distinct from t.location_id then update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop') and sync_round_id is null; end if; v_ping := v_loc is distinct from t.location_id or t.last_steer_ping is null or t.last_steer_ping < now() - interval '2 seconds'; update teams set pos_x = nx, pos_y = ny, pos_at = now(), dropped = true, location_id = v_loc, state = 'idle', travel_to = null, travel_from = null, travel_started_at = null, travel_arrive_at = null, visit_missions = case when v_loc is distinct from t.location_id then 0 else visit_missions end, last_steer_ping = case when v_ping then now() else last_steer_ping end where id = t.id; if v_loc is not null and v_loc is distinct from t.location_id then if t.jammed_until is null or t.jammed_until < now() then perform _feed(t.arena_id, 'squad.arrived', jsonb_build_object('team', t.number, 'location', v_loc)); end if; select count(*) into v_others from teams x where x.arena_id = t.arena_id and x.ready and x.id <> t.id and x.location_id = v_loc; if v_others > 0 then perform _feed(t.arena_id, 'encounter.detected', jsonb_build_object('location', v_loc, 'squads', v_others + 1)); perform _ping_arena(t.arena_id, 'encounter'); end if; end if; if v_ping then perform _ping_team(t.id, 'move'); end if; return jsonb_build_object('x', nx, 'y', ny, 'location', v_loc, 'clamped', d > maxd); end $$; create or replace function _respawn(p_team uuid, p_reason text) returns void language plpgsql as $$ declare t teams; a arenas; xy float8[]; v_safe text; begin select * into t from teams where id = p_team for update; if t.state <> 'recovery' then return; end if; update mission_instances set status = case when status = 'active' then 'expired' else status end where team_id = p_team and kind = 'recovery' and status = 'active'; update teams set state = 'idle', recovery_deadline = null, hp = _cfg(t.event_id, 'hp_respawn'), protected_until = now() + _secs(_cfg(t.event_id, 'protect_seconds')) where id = p_team; select * into a from arenas where id = t.arena_id; xy := _team_xy(t); if a.phase = 'play' and not _in_circle(_zone_circle(a.event_id, a.zone_stage), xy[1], xy[2]) then v_safe := _nearest_safe_xy(a.event_id, a.zone_stage, xy[1], xy[2]); if v_safe is not null then update teams set location_id = v_safe, pos_x = (_loc_xy(v_safe))[1], pos_y = (_loc_xy(v_safe))[2], pos_at = now(), visit_missions = 0 where id = p_team; end if; end if; perform _feed(t.arena_id, 'recovery.completed', jsonb_build_object('team', t.number, 'how', p_reason)); perform _ping_team(p_team, 'recovery'); end $$; create or replace function _arrive(p_team uuid) returns void language plpgsql as $$ declare t teams; a arenas; v_from locations; v_to locations; v_count int; begin select * into t from teams where id = p_team for update; if t.state <> 'traveling' then return; end if; select * into a from arenas where id = t.arena_id; select * into v_from from locations where id = t.travel_from; select * into v_to from locations where id = t.travel_to; update teams set state = 'idle', location_id = travel_to, travel_to = null, travel_from = null, travel_arrive_at = null, travel_started_at = null, travel_fx = null, travel_fy = null, dropped = true, visit_missions = 0 where id = p_team; if a.zone_next_at is not null and a.zone_stage < 5 and t.travel_fx is not null and not _in_circle(_zone_circle(a.event_id, a.zone_stage + 1), t.travel_fx, t.travel_fy) and _in_circle(_zone_circle(a.event_id, a.zone_stage + 1), v_to.x, v_to.y) then perform _apply(p_team, 'relocation', _cfg(a.event_id, 'pts_relocation'), 0, 0, 0, 'reloc-' || (a.zone_stage + 1), 'Reached safety before the zone collapsed'); end if; if t.jammed_until is null or t.jammed_until < now() then perform _feed(t.arena_id, 'squad.arrived', jsonb_build_object('team', t.number, 'location', v_to.id)); end if; select count(*) into v_count from teams where arena_id = t.arena_id and location_id = v_to.id and id <> t.id and ready; if v_count > 0 then perform _feed(t.arena_id, 'encounter.detected', jsonb_build_object('location', v_to.id, 'squads', v_count + 1)); perform _ping('arena-' || t.arena_id::text, 'encounter'); end if; if a.phase = 'play' and not exists (select 1 from mission_instances where team_id = p_team and status = 'active' and kind <> 'battle') then perform _start_location_mission(p_team); end if; perform _ping_team(p_team, 'arrived'); end $$; create or replace function _spawn_airdrop(p_arena uuid, p_location text, p_tier text) returns uuid language plpgsql as $$ declare a arenas; v_loc text := p_location; v_tpl text; v_id uuid; v_tier text := coalesce(p_tier, 'common'); begin select * into a from arenas where id = p_arena; if v_loc is null then select id into v_loc from locations where enabled and kind <> 'start' and id <> 'tr14' and _in_circle(_zone_circle(a.event_id, least(5, a.zone_stage + 1)), x, y) order by (tags && array['airdrop', 'public']) desc, random() limit 1; if v_loc is null then v_loc := 'tr14'; end if; end if; select id into v_tpl from mission_templates where kind = 'airdrop' and status = 'published' and id not in (select template_id from airdrops where arena_id = p_arena) order by random() limit 1; if v_tpl is null then select id into v_tpl from mission_templates where kind = 'airdrop' and status = 'published' order by random() limit 1; end if; if v_tpl is null then raise exception 'NO_AIRDROP_TEMPLATE'; end if; insert into airdrops(arena_id, location_id, tier, template_id, expires_at) values (p_arena, v_loc, v_tier, v_tpl, now() + _secs(_cfg(a.event_id, 'airdrop_window'))) returning id into v_id; update arenas set last_airdrop_at = now() where id = p_arena; perform _feed(p_arena, 'airdrop.spawned', jsonb_build_object('location', v_loc, 'tier', v_tier)); return v_id; end $$;
